语音配置
定义一个异步函数 getVoices，通过 OpenAPI 获取可用的音色列表。该步骤为可选操作，你使用系统默认音色，也可以在代码中输入音色 ID 修改为其他音色。
async function getVoices() {\n
    const api = new CozeAPI({\n
      token: getToken,\n
      baseURL: COZE_CN_BASE_URL,\n
      allowPersonalAccessTokenInBrowser: true,\n
    });\n
    const voices = await api.audio.voices.list();\n
    return voices.voice_list;\n
  }
async function getVoices() {
const api = new CozeAPI({
token: getToken,
baseURL: COZE_CN_BASE_URL,
allowPersonalAccessTokenInBrowser: true,
});
const voices = await api.audio.voices.list();
return voices.voice_list;
}
客户端初始化
定义一个异步函数 initClient，用于初始化一个实时通话客户端（RealtimeClient）。该函数包括检查设备权限、获取音色列表、配置客户端参数，并最终创建客户端实例。
async function initClient() {\n
    // 检查设备权限\n
    const permission = await RealtimeUtils.checkDevicePermission(true);\n
    if (!permission.audio) {\n
      throw new Error('需要麦克风访问权限');\n
    }\n
    setIsSupportVideo(permission.video);\n
\n
    // 获取音色列表\n
    const voices = await getVoices();\n
\n
    // 初始化客户端\n
    const client = new RealtimeClient({\n
      accessToken: getToken,\n
      botId,\n
      connectorId: '1024',\n
      voiceId: voices.length > 0 ? voices[0].voice_id : undefined,\n
      allowPersonalAccessTokenInBrowser: true,\n
      debug: true,\n
      videoConfig: permission.video\n
        ? { renderDom: 'local-player' }\n
        : undefined,\n
    });\n
\n
    clientRef.current = client;\n
    handleMessageEvent(); // 下面会实现\n
  }
async function initClient() {
// 检查设备权限
const permission = await RealtimeUtils.checkDevicePermission(true);
if (!permission.audio) {
throw new Error('需要麦克风访问权限');
}
setIsSupportVideo(permission.video);
// 获取音色列表
const voices = await getVoices();
// 初始化客户端
const client = new RealtimeClient({
accessToken: getToken,
botId,
connectorId: '1024',
voiceId: voices.length > 0 ? voices[0].voice_id : undefined,
allowPersonalAccessTokenInBrowser: true,
debug: true,
videoConfig: permission.video
? { renderDom: 'local-player' }
: undefined,
});
clientRef.current = client;
handleMessageEvent(); // 下面会实现
}
消息处理
定义了一个异步函数 handleMessageEvent，它是一个消息事件监听器，用于处理从实时通话服务器接收到的消息事件，并根据事件类型更新消息列表。
本示例代码仅对部分消息类型进行了处理，主要用于展示实时语音交互中的文本消息内容。开发者可根据实际需求对消息处理逻辑进行扩展或调整。
const handleMessageEvent = async () => {\n
    let lastEvent: any;\n
\n
    clientRef.current?.on(EventNames.ALL_SERVER, (eventName, event: any) => {\n
      // 只处理消息增量更新和完成事件\n
      if (\n
        event.event_type !== ChatEventType.CONVERSATION_MESSAGE_DELTA &&\n
        event.event_type !== ChatEventType.CONVERSATION_MESSAGE_COMPLETED\n
      ) {\n
        return;\n
      }\n
      \n
      const content = event.data.content;\n
      setMessageList(prev => {\n
        // 处理增量更新\n
        if (lastEvent?.event_type === ChatEventType.CONVERSATION_MESSAGE_DELTA) {\n
          return [...prev.slice(0, -1), prev[prev.length - 1] + content];\n
        }\n
        // 处理新消息\n
        if (event.event_type === ChatEventType.CONVERSATION_MESSAGE_DELTA) {\n
          return [...prev, content];\n
        }\n
        return prev;\n
      });\n
      lastEvent = event;\n
    });\n
  };
const handleMessageEvent = async () => {
let lastEvent: any;
clientRef.current?.on(EventNames.ALL_SERVER, (eventName, event: any) => {
// 只处理消息增量更新和完成事件
if (
event.event_type !== ChatEventType.CONVERSATION_MESSAGE_DELTA &&
event.event_type !== ChatEventType.CONVERSATION_MESSAGE_COMPLETED
) {
return;
}
const content = event.data.content;
setMessageList(prev => {
// 处理增量更新
if (lastEvent?.event_type === ChatEventType.CONVERSATION_MESSAGE_DELTA) {
return [...prev.slice(0, -1), prev[prev.length - 1] + content];
}
// 处理新消息
if (event.event_type === ChatEventType.CONVERSATION_MESSAGE_DELTA) {
return [...prev, content];
}
return prev;
});
lastEvent = event;
});
};
核心功能实现
语音通话的核心功能包括连接、断开、打断以及麦克风控制。以下是相关功能函数的实现：
// 连接\n
  const handleConnect = async () => {\n
    try {\n
      if (!clientRef.current) {\n
        await initClient();\n
      }\n
      await clientRef.current?.connect();\n
      setIsConnected(true);\n
    } catch (error) {\n
      // 错误处理...\n
    }\n
  };\n
\n
  // 打断\n
  const handleInterrupt = () => {\n
    try {\n
      clientRef.current?.interrupt();\n
    } catch (error) {\n
      message.error('打断失败：' + error);\n
    }\n
  };\n
\n
  // 断开连接\n
  const handleDisconnect = () => {\n
    try {\n
      clientRef.current?.disconnect();\n
      clientRef.current?.clearEventHandlers();\n
      clientRef.current = null;\n
      setIsConnected(false);\n
    } catch (error) {\n
      message.error('断开失败：' + error);\n
    }\n
  };\n
\n
  // 麦克风控制\n
  const toggleMicrophone = async () => {\n
    try {\n
      await clientRef.current?.setAudioEnable(!audioEnabled);\n
      setAudioEnabled(!audioEnabled);\n
    } catch (error) {\n
      message.error('切换麦克风状态失败：' + error);\n
    }\n
  };
