步骤二：检查设备权限
在初始化 SDK 之前，需确保当前项目已获取设备的麦克风访问权限。如果项目涉及视频通话功能，还需申请摄像头权限。以下是检查设备权限的代码示例：
import { RealtimeUtils } from "@coze/realtime-api";\n
\n
// 检查设备权限\n
const checkVideo = false; // 如需申请摄像头权限，请设置为 true\n
const result = await RealtimeUtils.checkDevicePermission();\n
\n
// 检查麦克风权限\n
if (!result.audio) {\n
    throw new Error("需要麦克风访问权限");\n
}\n
// 如果申请摄像头权限，还需检查摄像头权限\n
if (checkVideo && !result.video) {\n
    throw new Error("需要摄像头访问权限");\n
}
import { RealtimeUtils } from "@coze/realtime-api";
