示例代码
完整的示例代码如下。你也可以参考\n跑通示例项目获取更多示例代码。
import { EventNames, RealtimeClient, RealtimeUtils } from "@coze/realtime-api";\n
\n
async function initClient() {\n
    try {\n
        // 1. 检查设备权限\n
        const result = await RealtimeUtils.checkDevicePermission();\n
        if (!result.audio) {\n
            throw new Error("需要麦克风访问权限");\n
        }\n
\n
        // 2. 初始化客户端\n
        const client = new RealtimeClient({\n
            accessToken: 'your access token',\n
            botId: 'your bot id',\n
            connectorId: '1024',\n
            allowPersonalAccessTokenInBrowser: true,\n
        });\n
\n
        // 3. 配置事件监听\n
        client.on(EventNames.ALL, (eventName, data) => {\n
            console.log(eventName, data);\n
        });\n
\n
        // 4. 建立与服务端的连接\n
        await client.connect();\n
        \n
        // 返回初始化完成的客户端实例\n
        return client;\n
    } catch (error) {\n
        console.error('初始化失败:', error);\n
        throw error;\n
    }\n
}
