错误处理
系统定义了一个错误处理机制，用于处理 RealtimeClient 在运行过程中可能遇到的各种错误。通过定义一个枚举 RealtimeError，系统将不同的错误类型进行了分类，便于开发者根据具体的错误类型进行针对性的处理。
enum RealtimeError { \n
  DEVICE_ACCESS_ERROR = 'DEVICE_ACCESS_ERROR',         // 设备访问错误\n
  CONNECTION_ERROR = 'CONNECTION_ERROR',               // 连接错误\n
  DISCONNECTION_ERROR = 'DISCONNECTION_ERROR',         // 断开连接错误\n
  INTERRUPT_ERROR = 'INTERRUPT_ERROR',                 // 中断错误\n
  EVENT_HANDLER_ERROR = 'EVENT_HANDLER_ERROR',         // 事件处理错误\n
  NETWORK_ERROR = 'NETWORK_ERROR',                     // 网络错误\n
  CREATE_ROOM_ERROR = 'CREATE_ROOM_ERROR'             // 创建房间错误\n
}
